#!/usr/bin/env bash
# Bundle the React islands in web/src into the committed asset that
# internal/ui embeds. esbuild runs as a Go tool (see the tool block in
# go.mod), so the only thing npm supplies is web/node_modules; the pinned
# esbuild version plus web/package-lock.json are what make the output
# reproducible enough for the drift gate to be meaningful.
set -euo pipefail

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo_root="$(cd "$script_dir/.." && pwd)"
cd "$repo_root"

if [[ ! -d web/node_modules ]]; then
	printf 'web/node_modules is missing; run `npm ci` in web/ first.\n' >&2
	exit 1
fi

mkdir -p internal/ui/static

# --legal-comments=eof keeps every bundled dependency's @license banner in
# the output. The bundle is embedded into release binaries, so those notices
# have to travel with it; THIRD-PARTY-NOTICES.md carries the full licence
# texts the banners refer to.
#
# --sourcemap emits a linked map: a separate internal/ui/static/dashboard.js.map
# plus a //# sourceMappingURL=dashboard.js.map comment at the end of the bundle.
# A browser only fetches the map when devtools are open, so the linked form
# costs a page load nothing while still making a minified island stack trace
# readable; =inline would instead paste the whole map into the bundle every page
# load, and =external would drop the comment and leave nobody able to find it.
# The map keeps its sourcesContent (esbuild's default): the static handler has a
# flat namespace and serves no web/src tree, so a map without embedded sources
# would resolve to nothing but 404s in devtools. Both files are committed and
# embedded, exactly like the bundle itself.
go tool esbuild web/src/dashboard.tsx \
	--bundle \
	--minify \
	--format=esm \
	--target=es2020 \
	--jsx=automatic \
	--define:process.env.NODE_ENV='"production"' \
	--legal-comments=eof \
	--sourcemap \
	--banner:js='// Code generated by scripts/bundle-web.sh from web/src. DO NOT EDIT.' \
	--log-level=warning \
	--outfile=internal/ui/static/dashboard.js
